-- Ties 12 of the mock talent roster to real model_profiles, real logins,
-- real agency_model_relationships (Vantage Model Mgmt. / Meridian Models /
-- Solenne only -- all three already real with staff logins and already
-- distributed to all 3 real campaigns, so no new agency infrastructure is
-- needed), and real submissions on the 3 real campaigns. Same profile now
-- resolves consistently under brand selection, agency roster, and model
-- login -- not three disconnected mock representations of the same person.
-- Run after 0044 (fictional agency names), so it references the new names.
--
-- handle_new_user() (tightened in 0021_signup_role_lock_and_admin_lockout_
-- guard.sql) only auto-creates a profiles row straight from raw_user_meta_data
-- for role in ('brand_staff','agency_staff') -- anything else, including
-- 'model', falls through to its invite-lookup branch and requires a real
-- pending invites row matching the email, or it raises. So each model gets a
-- real invites row inserted first (status defaults to 'pending'), exactly
-- the same mechanism createModelInvite() uses in the live app -- this isn't
-- a workaround, it's going through the front door.
--
-- Petra Novak and Priya Sharma (the model) are deliberately left out of
-- this pass: Petra's mother/boutique split doesn't map onto these three
-- agencies without losing that nuance, and Priya Sharma the model would
-- collide in name with Priya Sharma, Solenne's real Booking Coordinator
-- (a different person in this fictional roster) -- both stay mock-only
-- until there's a reason to give them real accounts.

-- AW25 was only ever distributed to Vantage + Meridian -- Solenne now has
-- a real model on it (Caleb Stone) and needs the same access.
insert into campaign_agency_distributions (campaign_id, agency_org_id, invited_by_profile_id)
select '989ed703-b02a-4f2a-99c8-0f95b7540dff', o.id, (select id from profiles where email = 'marcus@acnestudios.example')
from organizations o where o.name = 'Solenne'
and not exists (select 1 from campaign_agency_distributions where campaign_id = '989ed703-b02a-4f2a-99c8-0f95b7540dff' and agency_org_id = o.id);

do $$
declare
  v_profile uuid := gen_random_uuid();
  v_agency_id uuid;
  v_model_id uuid;
begin
  select id into v_agency_id from organizations where name = 'Vantage Model Mgmt.';

  insert into invites (email, role, org_id, agency_relationship_type)
  values ('zara.okafor@elitetalent.example', 'model', v_agency_id, 'mother');

  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password,
    email_confirmed_at, created_at, updated_at,
    raw_app_meta_data, raw_user_meta_data, is_super_admin,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token
  ) values (
    '00000000-0000-0000-0000-000000000000', v_profile, 'authenticated', 'authenticated',
    'zara.okafor@elitetalent.example', crypt('placeholder-test-pw', gen_salt('bf')),
    now(), now(), now(), '{"provider":"email","providers":["email"]}',
    '{"role":"model","full_name":"Zara Okafor"}', false,
    '', '', '', '', '', '', '', ''
  );

  insert into auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (gen_random_uuid(), v_profile::text, v_profile, jsonb_build_object('sub', v_profile::text, 'email', 'zara.okafor@elitetalent.example'), 'email', now(), now(), now());

  insert into model_profiles (profile_id, full_name, location, default_day_rate, height, bust, waist, dress, experience, photo_url)
  values (v_profile, 'Zara Okafor', 'New York, NY', 980, '5''10"', '34"', '24"', 'US 4', '8 yrs', 'data:image/jpeg;base64,')
  returning id into v_model_id;

  insert into agency_model_relationships (model_id, agency_org_id, relationship_type)
  values (v_model_id, v_agency_id, 'mother');

  insert into agency_model_relationships (model_id, agency_org_id, relationship_type)
  select v_model_id, o.id, 'boutique' from organizations o where o.name = 'Kindred Talent';

  insert into submissions (campaign_id, model_id, submitting_agency_id, submitted_by_profile_id, stage, rate_quoted, notes, reviewed_by_profile_id, reviewed_at)
  values (
    '989ed703-b02a-4f2a-99c8-0f95b7540dff', v_model_id, v_agency_id,
    (select id from profiles where email = 'sophie@elite.example'),
    'approved', 980, null, (select id from profiles where email = 'marcus@acnestudios.example'), now() - interval '2 days'
  );

  raise notice 'Model test login added: zara.okafor@elitetalent.example (password: placeholder-test-pw)';
end $$;

